// Builds supabase/phesmun/apply-all-migrations.sql: every committed migration, unchanged and in order,
// wrapped in one transaction with a target-identity guard and the Supabase migration ledger rows.
// Run the output once in the PHESMUN project's SQL editor. It refuses any other database.
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
const REF = "gglltljhdpkfjnyjmnif";
const MARKER = `conference-os-target=phesmun ref=${REF}`;
const dir = new URL("../supabase/migrations/", import.meta.url);
const files = readdirSync(dir).filter(f => /^\d{14}_.+\.sql$/.test(f)).sort();
const out = [
  `-- PHESMUN OS: apply all ${files.length} Conference OS migrations to Supabase project ${REF} (PHESMUN - Production).`,
  `-- Generated by scripts/build-phesmun-migration-bundle.mjs from the committed files; do not edit by hand.`,
  `-- Paste the WHOLE file into the SQL editor of project ${REF} and run it once.`,
  `-- One transaction: on any error nothing is applied. It refuses any database without the PHESMUN target marker.`,
  `begin;`,
  `do $guard$ begin`,
  ` if to_regnamespace('supabase_migrations') is null or coalesce(obj_description('supabase_migrations'::regnamespace,'pg_namespace'),'') <> '${MARKER}' then`,
  `  raise exception 'Target guard: this is not the PHESMUN database (${REF}). Nothing was applied.'; end if;`,
  ` if exists(select 1 from supabase_migrations.schema_migrations) or to_regclass('public.conferences') is not null then`,
  `  raise exception 'Target guard: migrations already present. Nothing was applied.'; end if;`,
  `end $guard$;`,
];
for (const file of files) {
  const sql = readFileSync(new URL(file, dir), "utf8");
  const [, version, name] = file.match(/^(\d{14})_(.+)\.sql$/);
  const sha = createHash("sha256").update(sql).digest("hex");
  if (sql.includes("$ledger$")) throw Error(`${file} contains the ledger quote tag`);
  out.push(``, `-- ===== ${file} (sha256 ${sha}) =====`, sql.trimEnd(),
    `insert into supabase_migrations.schema_migrations(version,name,statements) values('${version}','${name}',array[$ledger$-- applied from supabase/migrations/${file} (sha256 ${sha})$ledger$]);`);
}
out.push(``, `do $verify$ begin`, ` if (select count(*) from supabase_migrations.schema_migrations) <> ${files.length} then raise exception 'Ledger count mismatch'; end if;`, `end $verify$;`, `commit;`,
  `select version, name from supabase_migrations.schema_migrations order by version;`, ``);
const target = new URL("../supabase/phesmun/apply-all-migrations.sql", import.meta.url);
writeFileSync(target, out.join("\n"));
console.log(`${files.length} migrations -> ${target.pathname} (${out.join("\n").length} bytes)`);
